import sys

def max_students_to_lunch(n, groups, k, x, a, b):
    total_lunches = k * x
    dp = [[False] * (total_lunches + 1) for _ in range(b + 1)]
    dp[0][0] = True

    for group_size in groups:
        new_dp = [row[:] for row in dp]
        for num_students in range(b, -1, -1):
            for lunches_used in range(total_lunches, -1, -1):
