                    if num_students + group_size <= b and lunches_used + group_size <= total_lunches:
                        new_dp[num_students + group_size][lunches_used + group_size] = True
        dp = new_dp

    max_students = -1
    for num_students in range(a, b + 1):
        for lunches_used in range(total_lunches + 1):
            if dp[num_students][lunches_used] and lunches_used == num_students:
                max_students = max(max_students, num_students)

    return max_students if max_students != -1 else 'impossible'

